      log('info', 'Could not check for existing user, will attempt to seed');
    }

    // Create demo user
    log('info', 'Creating demo user...');
    demoUser = await adminPb.collection('users').create({
      email: 'demo@ethara.ai',
      password: 'deku-demo-pw-2026',
      passwordConfirm: 'deku-demo-pw-2026',
      emailVisibility: true,
    });
    log('info', 'Demo user created', { userId: demoUser.id });

    const today = getToday();

    // Helper to get date N days ago
    function daysAgo(n) {
      const d = new Date(today);
      d.setDate(d.getDate() - n);
      return d.toISOString().split('T')[0];
    }

    // Create habits
    const meditateHabit = await adminPb.collection('habits').create({
      user_id: demoUser.id,
